function decorate(e,label){var box=document.querySelector('.ol-ing-sheet');if(!box)return;var title=box.querySelector('h3');if(!title||title.textContent.trim()!==label.trim())return;var role=box.querySelector('.ol-ing-role');if(role)role.textContent=e.role;Array.prototype.slice.call(box.querySelectorAll('.ol-ing-label')).forEach(function(h){if(h.textContent.trim()==='What we know'){var p=h.nextElementSibling;if(p)p.remove();h.remove()}});var source=make('a','ol-ing-source',e.source.indexOf('law.cornell.edu')>=0?'US food-use regulation (21 CFR; Cornell mirror)':'FDA ingredient inventory');source.href=e.source;source.target='_blank';source.rel='noopener noreferrer';var nodes=[make('h4','ol-ing-label','Form and origin'),make('p','',e.form),make('h4','ol-ing-label','Use conditions and evidence limits'),make('p','',e.difference),source,make('p','ol-ing-review-date','Identity/food-use sources checked '+e.reviewed+' · existing health reviews unchanged; no new clinical verdict or product assessment.')];var hs=box.querySelectorAll('.ol-ing-label');for(var i=0;i<hs.length;i++)if(hs[i].textContent.trim()==='Label says'&&hs[i].nextElementSibling){hs[i].nextElementSibling.after.apply(hs[i].nextElementSibling,nodes);return}nodes.forEach(function(n){box.append(n)})}
