var profiles=["vanilla","strawberry","raspberry","blueberry","cherry","orange","lemon","lime","grape","apple","peach","mango","pineapple","banana","chocolate","caramel","coconut","almond","peanut","butter","cheese","mint","peppermint","cinnamon","coffee","mixed berry","tropical fruit"];
