var next=Object.assign({},api);next.__namedFlavorProfiles=true;next.lookup=function(label){return api.lookup(label)||resolve(label)};next.render=function(text){var root=api.render(text);root.querySelectorAll('.ol-ing-row').forEach(function(row){var name=row.querySelector('.ol-ing-row-name'),meta=row.querySelector('.ol-ing-row-meta');if(!name||api.lookup(name.textContent))return;var label=name.textContent,e=resolve(label);if(!e)return;if(meta&&!row.dataset.evidence&&!row.dataset.watchWord)meta.textContent=e.use+' · form/source unspecified  ›';var open=row.onclick;if(typeof open==='function')row.onclick=function(event){open.call(this,event);decorate(e,label)}});return root};window.OLIngredients=next;window.OLNamedFlavorProfiles={resolve:resolve,profiles:profiles.slice(),version:'20261011-profiles1'};
