function norm(s){return String(s||'').trim().toLowerCase().replace(/[\u2010-\u2015\u2212]/g,'-').replace(/[\u2018\u2019\u2032]/g,"'").replace(/\s+/g,' ')}
function direct(s){var keys=Object.keys(aliases);for(var i=0;i<keys.length;i++)if(aliases[keys[i]].indexOf(norm(s))>=0)return keys[i];return null}
function resolve(label){var n=norm(label),key=direct(n);if(key)return key;var m=/^([^()]+)\s*\(as\s+([^()]+)\)$/.exec(n);if(!m)return null;var nutrient=direct(m[1]),form=direct(m[2]);if(!nutrient||nutrient!==form)return null;if(nutrient==='d'&&((norm(m[1])==='vitamin d2'&&['ergocalciferol','vitamin d2'].indexOf(norm(m[2]))<0)||(norm(m[1])==='vitamin d3'&&['cholecalciferol','vitamin d3'].indexOf(norm(m[2]))<0)))return null;return nutrient}
var api={version:'0.2.0',entries:E,sources:R,reviews:reviews,resolve:resolve,aliases:aliases,refresh:sync};if(typeof module==='object'&&module.exports){module.exports=api;return}root.OLIngredientEducation=api;
var doc=root.document;function el(tag,text,cls){var e=doc.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e}
function link(ref){var a=el('a',ref[0]+' · '+(ref[2]||'Reference synthesis'));a.href=ref[1];a.target='_blank';a.rel='noopener noreferrer';return a}
function sync(){doc.querySelectorAll('.ol-ing-sheet').forEach(function(box){var title=box.querySelector('h3');if(!title)return;var label=title.textContent.trim(),old=box.querySelector('.ie-pilot');if(old&&old.dataset.label===label&&old.dataset.version===api.version)return;if(old)old.remove();var section=el('section',null,'ie-pilot');section.dataset.label=label;section.dataset.version=api.version;section.append(el('h4','Ingredient education — research and amount context','ol-ing-label'));var key=api.resolve(label);if(!key){section.append(el('p','A deeper dose/evidence entry for this exact label term has not been added to this pilot. Existing identity/common-use information remains above. No risk or benefit is inferred from an unmatched name.'));box.append(section);return}
section.append(el('p','Label term: '+label),el('p','This ingredient name does not establish its amount, total daily intake, absorption, deficiency status or your current package. Elemental nutrient amounts cannot be inferred from compound names.'));
[['body','What it does in the body'],['research','What the references and research say'],['high','When intake is high'],['reference','Understanding reference limits'],['form','Form and absorption: what is supported'],['debate','Disagreement and evidence limitations']].forEach(function(pair){var claim=E[key][pair[0]];if(claim)section.append(el('h4',pair[1],'ol-ing-label'),el('p',claim[0]),link(R[claim[1]]))});
var review=reviews[key];if(review){section.append(el('h4','Source review and remaining gaps','ol-ing-label'),el('p','Reviewed '+review.date+'. '+review.status+'. '+review.read),el('p',review.disclosures),el('p',review.gaps))}else{section.append(el('h4','What remains unreviewed','ol-ing-label'),el('p','Reference-backed pilot assembled 2026-10-12. Funding/conflicts, a comprehensive search for competing studies and clinical review are incomplete.'))}section.append(el('p','The original named-form explanation stays separate. No nutrient totals, interaction checking, personalized dose advice or new evidence color is added.'));box.append(section)})}
