(function(root){'use strict';
var VERSION='0.1.0',DATA={"b12":{"title":"Vitamin B12","url":"https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/","names":["vitamin b12","vitamin b-12","cobalamin","cyanocobalamin","methylcobalamin","adenosylcobalamin","5-deoxyadenosylcobalamin","hydroxycobalamin","hydroxocobalamin"],"body":"B12 supports normal nerve function, red blood cell formation and DNA synthesis. A physiological requirement does not establish an added benefit from this product.","research":"NIH summarizes evidence that correcting B12 deficiency is important, but extra B12 does not improve energy or athletic performance when B12 status is already sufficient. Lowering homocysteine with B-vitamin supplements has not consistently translated into fewer heart attacks or deaths; combination trials cannot isolate every nutrient’s contribution.","high":"The US Food and Nutrition Board has not established a B12 upper limit because of its low toxicity potential. This is not a guarantee of benefit or unrestricted safety for every person. NIH describes mixed cancer findings; observational high blood B12 associations do not establish that supplementation caused cancer.","reference":"No US B12 tolerable upper intake level is established. An absent limit is not zero, an intake target or proof that unlimited doses are appropriate. No product amount, absorption or deficiency diagnosis is inferred here.","form":"Methylcobalamin and adenosylcobalamin are active forms; cyanocobalamin and hydroxycobalamin can be converted to active forms. NIH reports no evidence of different supplement absorption rates by form. An active-form name alone does not prove superior benefit or identify manufacturing source.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Vitamin B12 professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}},"folate":{"title":"Folate (B9)","url":"https://ods.od.nih.gov/factsheets/Folate-HealthProfessional/","names":["folate","vitamin b9","vitamin b-9","folic acid","5-mthf","l-5-mthf","methylfolate","l-methylfolate","5-methyltetrahydrofolate","l-5-methyltetrahydrofolate"],"body":"Folate supports DNA and RNA synthesis, cell division and amino-acid metabolism. Its normal roles do not establish a benefit from adding more when intake is adequate.","research":"NIH summarizes strong evidence for folic acid in neural-tube-defect prevention around conception, but this is not proof that every folate form or fortified product produces identical outcomes. Homocysteine lowering is not equivalent to preventing all cardiovascular events; stroke findings vary with population and baseline folate status. No pregnancy-specific dose is prescribed here.","high":"Large folate intakes can correct the anemia of B12 deficiency without correcting neurological injury, potentially delaying recognition. Cancer findings depend on timing, baseline status and study design and do not justify a general product-level cancer verdict.","reference":"The US adult upper limit at age 19 and older is 1,000 mcg/day folic acid from supplements and fortified foods; it excludes naturally occurring food folate. Do not compare that folic-acid mass directly with mcg DFE or automatically apply it to an unverified 5-MTHF amount. Children have lower limits. No conversion or intake total is computed.","form":"Folate is a family term; folic acid and 5-MTHF are distinct forms. Dietary folate equivalents account for bioavailability, not a universal quality ranking. A generic folate label does not identify the exact compound. No genetic suitability, automatic form preference or manufacturing source is inferred.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Folate (B9) professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}},"vc":{"title":"Vitamin C","url":"https://ods.od.nih.gov/factsheets/VitaminC-HealthProfessional/","names":["vitamin c","ascorbic acid","l-ascorbic acid","sodium ascorbate","calcium ascorbate"],"body":"Vitamin C supports collagen formation, normal immune function and antioxidant processes and improves absorption of nonheme iron. These roles do not mean a scanned product prevents infections.","research":"NIH summarizes that regular vitamin C supplementation does not generally prevent colds in the general population, although duration may be modestly shorter; starting after symptoms has not shown consistent benefit. Oral supplement findings cannot be transferred to intravenous treatment, and antioxidant mechanisms are not proof of cancer or cardiovascular prevention.","high":"High intakes can cause diarrhea, nausea and abdominal cramps. Concerns about kidney stones and iron overload are context-dependent, especially with relevant disorders; an ingredient name alone cannot establish those risks from this product.","reference":"The US adult upper limit at age 19 and older is 2,000 mg/day vitamin C from all sources. It is not a target, treatment dose or per-product safety cutoff. Children have lower limits, and medical treatment is a separate context.","form":"Ascorbic acid is a named vitamin C form. Sodium and calcium ascorbate are mineral salts; the name does not establish the vitamin C or mineral amount. NIH reports equivalent bioavailability for synthetic and naturally occurring ascorbic acid; this is not evidence that every formulation is clinically interchangeable.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Vitamin C professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}},"ca":{"title":"Calcium","url":"https://ods.od.nih.gov/factsheets/Calcium-HealthProfessional/","names":["calcium","calcium carbonate","calcium citrate","calcium citrate malate","calcium gluconate","calcium lactate","calcium phosphate","tricalcium phosphate","dicalcium phosphate","calcium sulfate","calcium sulphate"],"body":"Calcium contributes to bones and teeth and supports muscle contraction, nerve transmission and blood clotting. A normal role does not establish that this product prevents fractures.","research":"NIH summarizes mixed fracture-prevention results for calcium alone or with vitamin D. Changes in bone mineral density do not always establish clinically meaningful fracture reduction, and results depend on baseline intake, population and co-interventions. No universal supplement-benefit conclusion is assigned.","high":"Excess calcium can contribute to hypercalcemia or hypercalciuria in relevant contexts; supplements can also cause gastrointestinal symptoms. Evidence concerning supplemental calcium and cardiovascular outcomes is mixed. Neither the ingredient name nor a single calcium amount establishes personal harm or reassurance.","reference":"US total-intake upper limits are 2,500 mg/day calcium for adults age 19–50 and 2,000 mg/day for adults age 51 and older, counting food and supplements. They are not recommended doses or product cutoffs. Elemental calcium is not the entire calcium-compound mass; no intake calculation is performed.","form":"Carbonate and citrate contain different elemental-calcium proportions. Citrate is less dependent on stomach acid for absorption; formulation, food and amount also matter. This is not a universal best-form ranking. A calcium compound may serve nutritional or technical food functions; actual manufacturer purpose and dose remain unverified.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Calcium professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}},"k":{"title":"Potassium","url":"https://ods.od.nih.gov/factsheets/Potassium-HealthProfessional/","names":["potassium","potassium chloride","potassium citrate","potassium gluconate","potassium bicarbonate"],"body":"Potassium supports fluid balance, nerve transmission and muscle contraction. Its normal function does not establish an electrolyte or exercise benefit from an unspecified amount.","research":"NIH summarizes blood-pressure reductions in many potassium-supplement trials, particularly in people with hypertension, but effects differ across reviews and populations. Whole-diet studies and salt-substitute trials also change other nutrients or sodium, so they cannot always isolate potassium’s contribution.","high":"High potassium can cause dangerous hyperkalemia, especially with impaired kidney excretion or certain medicines. Very large supplemental or salt-substitute amounts can also cause acute problems in otherwise healthy people. This sheet does not assess kidney function, medication interactions or individual suitability.","reference":"The US reference assessment did not establish a potassium upper limit because evidence was insufficient to set one. That does not establish an unlimited safe dose. The label Daily Value of 4,700 mg is not an upper limit or a personal target; adequate-intake values have different scopes.","form":"Potassium chloride can occur in salt substitutes; citrate, gluconate and bicarbonate are other named salts. Supplement Facts declares elemental potassium, not whole-compound mass. Potassium iodide used in microgram quantities is an iodine source and is not matched here as potassium-dose evidence.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Potassium professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}},"iod":{"title":"Iodine","url":"https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/","names":["iodine","iodide","potassium iodide","sodium iodide","potassium iodate","calcium iodate"],"body":"Iodine is a component of thyroid hormones, which support metabolism and normal development. This role does not mean extra iodine improves thyroid function when intake is already sufficient.","research":"NIH distinguishes preventing iodine deficiency from extra supplementation in iodine-sufficient populations. Benefits of pregnancy supplementation for child neurodevelopment in mild-to-moderate deficiency remain uncertain in trials. Population iodine monitoring is not an individual diagnosis, and this sheet provides no pregnancy or thyroid treatment advice.","high":"Excess iodine can trigger underactive or overactive thyroid function in susceptible individuals. Responses depend on baseline status and thyroid conditions; some people can react at intakes tolerated by the general population. Kelp and other seaweeds can vary widely in iodine content and are not treated as verified iodine doses.","reference":"The US adult upper limit at age 19 and older is 1,100 mcg/day iodine from food and supplements. It is not a personal safe/harmful boundary or target. Children have lower limits; clinician-managed treatment is separate. No iodine intake is calculated from a compound name.","form":"Iodide and iodate are distinct forms; iodate is reduced to iodide before absorption. Potassium iodide and sodium iodide can supply iodine; iodates can also occur as dough conditioners. Names do not establish quantity, purpose, source or clinical equivalence. Kelp, seaweed and generic salt are deliberately not exact aliases.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"NIH ODS Iodine professional fact sheet: selected physiology, named forms, health-research and intake-risk sections. Clinical findings below summarize that reference, not an independently completed study review.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of the studies it cites. Underlying-study funding, author conflicts and sponsor roles were not independently audited in this batch; missing information is not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive competing-study searches remain incomplete. No named-form clinical ranking, deficiency diagnosis, medication checking, individualized intake target or product safety conclusion is established."}}};
function install(api){if(!api||!api.entries||!api.sources||!api.reviews||!api.aliases)throw Error('Nutrient batch requires extensible ingredient education');if(api.nutrientBatch1===VERSION)return api;var keys=Object.keys(DATA),seen=Object.create(null);Object.keys(api.aliases).forEach(function(k){api.aliases[k].forEach(function(n){seen[n]=k})});keys.forEach(function(k){var r=DATA[k];if(api.entries[k]||api.sources[k]||api.aliases[k])throw Error('Nutrient key already exists: '+k);r.names.forEach(function(n){if(seen[n])throw Error('Nutrient alias collision: '+n);seen[n]=k});['body','research','high','reference','form'].forEach(function(field){if(typeof r[field]!=='string'||!r[field])throw Error('Incomplete nutrient record')});if(!/^https:\/\//.test(r.url))throw Error('Invalid source')});keys.forEach(function(k){var r=DATA[k],entry={};['body','research','high','reference','form'].forEach(function(field){entry[field]=[r[field],k]});api.entries[k]=entry;api.sources[k]=[r.title,r.url,'NIH ODS reference synthesis; underlying-study audit partial'];api.reviews[k]=Object.assign({},r.review);api.aliases[k]=r.names.slice()});api.nutrientBatch1=VERSION;api.version='0.3.0';return api}
var exported={version:VERSION,records:DATA,install:install};if(typeof module==='object'&&module.exports){module.exports=exported;return}if(root.OLNutrientBatch1)return;var api=install(root.OLIngredientEducation);root.OLNutrientBatch1=exported;if(typeof api.refresh==='function')api.refresh();
})(typeof window==='object'?window:globalThis);
;

