(function(root){'use strict';
var VERSION='0.1.0',DATA={"va":{"title":"Vitamin A","url":"https://ods.od.nih.gov/factsheets/VitaminA-HealthProfessional/","groups":{"generic":["vitamin a"],"retinol":["retinol"],"acetate":["retinyl acetate","vitamin a acetate"],"palmitate":["retinyl palmitate","vitamin a palmitate"],"beta":["beta-carotene","beta carotene"]},"body":"Vitamin A supports normal vision, immune function and cell growth and differentiation. Normal physiological roles do not establish added benefit from this product when intake is adequate.","research":"NIH distinguishes preformed vitamin A (retinol and retinyl esters) from provitamin A carotenoids. Deficiency prevention and treatment evidence must not be transferred to routine extra supplementation or to every carotenoid. A generic vitamin A label does not establish the mixture of forms.","high":"Excess preformed vitamin A can accumulate and cause toxicity, including liver effects and birth defects. Beta-carotene has a different risk assessment: high-dose supplement findings in high-risk groups should not become a warning against ordinary carotenoid-containing foods. No pregnancy, smoking or deficiency status is inferred for the user.","reference":"The US adult upper limit at age 19 and older is 3,000 mcg/day preformed vitamin A, expressed as retinol activity equivalents, from food and supplements. It is not an upper limit for all carotenoids. For mixed forms, the preformed fraction must be known before comparison. No conversion from unknown-form IU, dose advice or intake calculation is performed.","form":"Retinol, retinyl acetate and retinyl palmitate are preformed vitamin A. Beta-carotene can be converted to vitamin A, with conversion dependent on source and context. Lutein, zeaxanthin and lycopene are not treated as vitamin A aliases. A named form does not establish manufacture, absorbed dose or personal suitability.","debate":"ATBC randomized 29,133 Finnish male smokers aged 50–69 to alpha-tocopherol, beta-carotene, both, or placebo for five to eight years. The beta-carotene regimen was 20 mg/day and increased lung-cancer incidence relative to no beta-carotene. This regimen-specific finding does not establish harm from food beta-carotene, ordinary fortified-food amounts, or every population. Study doses are descriptions, not recommendations.","trial":["ATBC trial (1994), PMID 8127329","https://pubmed.ncbi.nlm.nih.gov/8127329/","Randomized trial; abstract read"],"review":{"date":"2026-10-22","status":"Reference-backed education with selected trial context; partial audit; not clinically reviewed","read":"NIH ODS Vitamin A professional reference plus the linked selected trial at its stated review depth. This is not an exhaustive current clinical systematic review.","disclosures":"ATBC PubMed funding metadata lists NCI contract N01-CN-45165. The NCI study site describes collaboration between NCI and the Finnish public-health institute. Full author disclosures, sponsor roles and original trial documents were not audited; public funding is not a no-conflicts certification.","gaps":"Independent correction/retraction checks, comprehensive newer-study searches and underlying-study audits remain incomplete. Trial-specific risks are not universal ingredient or product verdicts."}},"ve":{"title":"Vitamin E","url":"https://ods.od.nih.gov/factsheets/VitaminE-HealthProfessional/","groups":{"generic":["vitamin e"],"alpha":["alpha-tocopherol","alpha tocopherol"],"alpha-acetate":["alpha-tocopheryl acetate","alpha tocopheryl acetate"],"alpha-succinate":["alpha-tocopheryl succinate","alpha tocopheryl succinate"],"rrr-alpha":["rrr-alpha-tocopherol","d-alpha-tocopherol"],"allrac-alpha":["all-rac-alpha-tocopherol","dl-alpha-tocopherol"],"rrr-acetate":["rrr-alpha-tocopheryl acetate","d-alpha-tocopheryl acetate"],"allrac-acetate":["all-rac-alpha-tocopheryl acetate","dl-alpha-tocopheryl acetate"]},"body":"Vitamin E has antioxidant activity and supports normal immune function. Alpha-tocopherol is the form recognized to meet human vitamin E requirements; a biochemical function does not establish that extra supplementation prevents disease.","research":"NIH summarizes that large trials generally have not supported routine vitamin E supplementation for cardiovascular prevention. Findings depend on dose, formulation, population and outcome. A benefit or adverse result from one alpha-tocopherol regimen cannot be transferred to all vitamin E-containing foods or other vitamin E compounds.","high":"High supplemental alpha-tocopherol can increase bleeding risk, with additional concern around anticoagulant or antiplatelet medicines. This is general education, not medication-interaction screening or a reason to change prescribed treatment. An ingredient name alone does not establish exposure.","reference":"The US adult upper limit at age 19 and older is 1,000 mg/day supplemental alpha-tocopherol, including the stereoisomer forms covered by that assessment. It is not a recommended dose or proof that every lower amount is harmless. IU interpretation and biological activity depend on form. No IU conversion or product-level safety cutoff is applied.","form":"RRR/d-alpha and all-rac/dl-alpha descriptions distinguish stereoisomer composition. Acetate and succinate are ester forms. These distinctions do not establish a universal clinically superior form or manufacturing origin. Mixed tocopherols and tocotrienols are not automatically matched to alpha-tocopherol intake or treatment evidence.","debate":"The 2011 SELECT analysis included 34,887 men in its primary analysis. The vitamin E-only regimen was 400 IU/day all-rac-alpha-tocopheryl acetate. Prostate-cancer incidence increased relative to placebo (hazard ratio 1.17, 99% CI 1.004–1.36); the absolute increase was 1.6 cases per 1,000 person-years. This is not a 17-percentage-point increase and does not describe every food, form or population.","trial":["SELECT follow-up (2011), PMID 21990298","https://pubmed.ncbi.nlm.nih.gov/21990298/","Randomized trial; abstract and funding metadata read"],"review":{"date":"2026-10-22","status":"Reference-backed education with selected trial context; partial audit; not clinically reviewed","read":"NIH ODS Vitamin E professional reference plus the linked selected trial at its stated review depth. This is not an exhaustive current clinical systematic review.","disclosures":"SELECT PubMed metadata lists NCI grants U10 CA037429 and CA37429; NCI describes itself as the primary funder. Full author disclosures, material-supply arrangements and sponsor roles were not audited in this batch. The selected trial is not an independent audit of all vitamin E evidence.","gaps":"Independent correction/retraction checks, comprehensive newer-study searches and underlying-study audits remain incomplete. Trial-specific risks are not universal ingredient or product verdicts."}},"vk":{"title":"Vitamin K","url":"https://ods.od.nih.gov/factsheets/VitaminK-HealthProfessional/","groups":{"generic":["vitamin k"],"k1":["vitamin k1","vitamin k-1","phylloquinone","phytonadione","phytomenadione"],"k2":["vitamin k2","vitamin k-2","menaquinone","menaquinones"],"mk4":["mk-4","mk4","menaquinone-4","menaquinone 4","vitamin k2 (mk-4)"],"mk7":["mk-7","mk7","menaquinone-7","menaquinone 7","vitamin k2 (mk-7)"]},"body":"Vitamin K supports proteins involved in blood clotting and bone metabolism. A normal role does not establish that extra K2 prevents fractures, reverses arterial calcium or improves outcomes from the scanned product.","research":"NIH describes mixed bone-health findings and uncertainty about calcification benefits. Changes in osteocalcin or matrix Gla-protein markers are not the same as fewer fractures or cardiovascular events. High-dose MK-4 treatment findings and K1 studies cannot automatically be transferred to ordinary MK-7 foods or supplements.","high":"Vitamin K can substantially affect warfarin and similar vitamin K antagonists. People taking those medicines need clinician-guided consistency, not an instruction from this app to eliminate vitamin K foods or change medicine. No medication use or individual suitability is inferred.","reference":"No US tolerable upper intake level has been established for vitamin K. This is not proof that unlimited amounts are appropriate or that medication interactions are absent. Intake-reference values, clinical treatment doses and product safety are different questions; this sheet sets no personal target.","form":"K1/phylloquinone/phytonadione is distinct from the K2 menaquinone family. MK-4 and MK-7 are specific forms; generic K2 does not identify either. Longer circulation or altered biomarkers do not prove better clinical outcomes. Menadione/K3 and broad food sources such as natto are not exact K1/K2 nutrient-dose aliases.","debate":"AVADEC randomized 365 older men with established aortic-valve calcification to 720 mcg/day MK-7 plus 25 mcg/day vitamin D or placebo for 24 months. A vitamin K-related biomarker improved, but the primary valve-calcification progression outcome did not differ significantly. This combination trial does not isolate K2, establish fewer clinical events, or prove no benefit for women, other populations, forms or outcomes.","trial":["AVADEC randomized trial (2022)","https://pmc.ncbi.nlm.nih.gov/articles/PMC9047644/","Article methods, results, limitations and disclosures read"],"review":{"date":"2026-10-22","status":"Reference-backed education with selected trial context; partial audit; not clinically reviewed","read":"NIH ODS Vitamin K professional reference plus the linked selected trial at its stated review depth. This is not an exhaustive current clinical systematic review.","disclosures":"AVADEC reports Danish Heart Foundation, Region of Southern Denmark Research Council and Novo Nordisk Foundation grants. Kappa Bioscience and Orkla Care provided active/placebo tablets free; authors state funders had no role in design, conduct, analysis, writing or publication decision. Diederichsen reports an MK-7 GRAS-panel role; Møller reports industry advisory, speaker and research relationships outside this work; other authors report no conflicts. These are reported disclosures, not independent financial verification.","gaps":"Independent correction/retraction checks, comprehensive newer-study searches and underlying-study audits remain incomplete. The NIH K reference carries a 2021 update date; AVADEC adds 2022 evidence but does not make this a comprehensive 2026 review."}}};
function norm(v){return String(v==null?'':v).trim().toLowerCase().replace(/[\u2010-\u2015\u2212]/g,'-').replace(/\s+/g,' ')}
function identify(label){var n=norm(label),hit=null;Object.keys(DATA).some(function(k){return Object.keys(DATA[k].groups).some(function(g){if(DATA[k].groups[g].indexOf(n)>=0){hit={key:k,group:g};return true}return false})});return hit}
function compatible(a,b){if(!a||!b||a.key!==b.key)return false;if(a.group==='generic'||a.group===b.group)return true;if(a.key==='vk'&&a.group==='k2')return ['k2','mk4','mk7'].indexOf(b.group)>=0;if(a.key==='ve'&&a.group==='alpha')return ['alpha','rrr-alpha','allrac-alpha'].indexOf(b.group)>=0;if(a.key==='ve'&&a.group==='alpha-acetate')return ['alpha-acetate','rrr-acetate','allrac-acetate'].indexOf(b.group)>=0;return false}
function resolveAEK(label,previous){var direct=identify(label);if(direct)return direct.key;var m=/^([^()]+)\s*\(as\s+([^()]+)\)$/.exec(norm(label));if(m){var a=identify(m[1]),b=identify(m[2]);if(a||b)return compatible(a,b)?a.key:null}return previous(label)}
function install(api){if(!api||!api.entries||!api.sources||!api.reviews||!api.aliases||typeof api.resolve!=='function')throw Error('AEK requires extensible education');if(api.nutrientBatchAEK===VERSION)return api;var seen=Object.create(null),keys=Object.keys(DATA);Object.keys(api.aliases).forEach(function(k){api.aliases[k].forEach(function(n){seen[n]=k})});keys.forEach(function(k){if(api.entries[k]||api.sources[k]||api.sources[k+'trial']||api.aliases[k])throw Error('AEK key collision');Object.keys(DATA[k].groups).forEach(function(g){DATA[k].groups[g].forEach(function(n){if(seen[n])throw Error('AEK alias collision');seen[n]=k})})});var prior=api.resolve;keys.forEach(function(k){var r=DATA[k],e={};['body','research','high','reference','form'].forEach(function(f){e[f]=[r[f],k]});e.debate=[r.debate,k+'trial'];api.entries[k]=e;api.sources[k]=[r.title,r.url,'NIH ODS reference; audit partial'];api.sources[k+'trial']=r.trial.slice();api.reviews[k]=Object.assign({},r.review);api.aliases[k]=[].concat.apply([],Object.keys(r.groups).map(function(g){return r.groups[g]}))});api.resolve=function(label){return resolveAEK(label,prior)};api.nutrientBatchAEK=VERSION;api.version='0.4.0';return api}
var exported={version:VERSION,records:DATA,identify:identify,compatible:compatible,resolveAEK:resolveAEK,install:install};if(typeof module==='object'&&module.exports){module.exports=exported;return}if(root.OLNutrientBatchAEK)return;var api=install(root.OLIngredientEducation);root.OLNutrientBatchAEK=exported;if(typeof api.refresh==='function')api.refresh();
})(typeof window==='object'?window:globalThis);
;

/* --- nutrient-batch-scc.js --- */
(function(root){'use strict';
var VERSION='0.1.0',DATA={"se":{"title":"Selenium","url":"https://ods.od.nih.gov/factsheets/Selenium-HealthProfessional/","groups":{"generic":["selenium"],"methionine":["selenomethionine","l-selenomethionine"],"selenite":["sodium selenite"],"selenate":["sodium selenate"],"yeast":["selenium-enriched yeast","selenium enriched yeast","selenized yeast"]},"body":"Selenium is part of selenoproteins involved in thyroid-hormone metabolism, DNA synthesis, reproduction and protection from oxidative damage. These normal roles do not establish a benefit from extra selenium when intake is adequate.","research":"NIH distinguishes observational selenium-status associations from supplementation trials. SELECT did not establish prostate-cancer prevention from its 200 mcg/day selenomethionine regimen, and broader trial evidence does not establish routine cancer prevention. Baseline status, form and population matter; study doses are descriptions, not recommended intakes.","high":"Chronic excess can cause selenosis, including hair and nail problems and gastrointestinal or neurological effects. Plant-food selenium, especially Brazil nuts, can vary widely. A food-category average or ingredient name cannot establish a dose or diagnose excess in the product user.","reference":"The US adult upper limit at age 19 and older is 400 mcg/day selenium from food and supplements. EFSA’s 2023 adult upper limit is 255 mcg/day total dietary selenium, including supplements. Keep the authorities separate: these are risk-assessment references, not supplement targets or precise individual safe/harmful boundaries. Children have lower limits. No intake comparison is performed.","form":"Selenomethionine, sodium selenite and sodium selenate are distinct forms. Selenium-enriched yeast is a preparation, not verified pure selenomethionine. Form names alone do not establish composition, absorbed dose, manufacturing source or a universally superior clinical effect. Brazil nuts and generic yeast are not exact dose aliases.","debate":"EFSA’s 2023 assessment used alopecia as the critical effect, identified a 330 mcg/day total-intake lowest-observed-adverse-effect level from SELECT, and applied an uncertainty factor of 1.3 to derive 255 mcg/day. The 330 mcg value is not the supplement dose alone. This updated European assessment differs from the older US assessment; neither is an individual toxicity test.","extra":["EFSA selenium upper-limit assessment (2023)","https://pmc.ncbi.nlm.nih.gov/articles/PMC9854220/","Selected abstract, methods and reference-limit sections read"],"review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Selenium professional-reference sections; selected EFSA 2023 risk-assessment sections.","disclosures":"NIH is the reference publisher, not necessarily the funder of cited studies. Underlying trial funding, author conflicts and sponsor roles were not independently audited. EFSA’s selenium assessment was requested by the European Commission; individual declarations and contracted-review relationships were not fully audited.","gaps":"Independent correction/retraction checks and comprehensive current competing-evidence searches remain incomplete. The original US assessment and SELECT source documents were not independently audited in this batch."}},"cu":{"title":"Copper","url":"https://ods.od.nih.gov/factsheets/Copper-HealthProfessional/","groups":{"generic":["copper"],"oxide":["cupric oxide","copper(ii) oxide"],"sulfate":["cupric sulfate","cupric sulphate","copper sulfate","copper sulphate"],"gluconate":["copper gluconate"],"glycinate":["copper glycinate","copper bisglycinate"],"chelate":["copper amino acid chelate","copper amino acid chelates"]},"body":"Copper supports enzymes involved in energy production, iron metabolism, connective-tissue synthesis and nervous-system functions. A normal role does not establish that additional copper improves those outcomes.","research":"The NIH reference describes mixed observational cardiovascular and cognitive findings and limited supplementation evidence. Serum copper and ceruloplasmin can be influenced by inflammation, pregnancy and other factors; a high blood concentration does not prove that dietary copper caused disease. Biomarker changes do not establish fewer cardiovascular events or dementia prevention.","high":"Chronic excessive copper exposure can cause gastrointestinal symptoms and liver injury. Wilson’s disease is an important example of altered copper handling, not a condition this app diagnoses. General-population reference limits do not establish personal suitability, and medically supervised treatment is separate.","reference":"The US adult upper limit at age 19 and older is 10 mg/day copper from food and supplements. It is not a daily target, product cutoff or recommendation to add copper. Children have lower limits. Keep mg and mcg explicit; compound mass and elemental copper are not interchangeable, and no conversion or intake total is computed here.","form":"Named nutrient forms include cupric oxide, cupric sulfate, copper gluconate and amino-acid chelates. The NIH reference does not provide a comparative bioavailability basis for ranking them; its older publication date does not establish that no newer research exists. Copper chlorophyllin and generic copper-containing mixtures are not automatically treated as verified copper doses.","debate":"Sustained excessive zinc intake can inhibit copper absorption and contribute to copper deficiency. That interaction does not mean every zinc user should automatically add copper. This sheet does not calculate a zinc:copper ratio, diagnose deficiency, or recommend a supplement combination.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Copper professional-reference sections.","disclosures":"NIH is the reference publisher, not necessarily the funder of cited studies. Underlying-study funding, author conflicts and sponsor roles were not independently audited; missing disclosures are not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive current competing-evidence searches remain incomplete. The NIH reference carries an October 18, 2022 update date; selected-reference review is not a current systematic clinical review."}},"cho":{"title":"Choline","url":"https://ods.od.nih.gov/factsheets/Choline-HealthProfessional/","groups":{"generic":["choline"],"bitartrate":["choline bitartrate"],"phosphatidylcholine":["phosphatidylcholine"]},"body":"Choline supports cell-membrane phospholipids, acetylcholine production, methyl-group metabolism and lipid transport. The body produces some choline, but dietary choline is still needed. These roles are not proof that extra supplementation improves memory.","research":"The NIH reference describes limited and mixed cognitive evidence. A role in acetylcholine production does not establish memory improvement in healthy people. Severe-restriction and parenteral-nutrition findings do not establish that an ordinary supplement treats fatty liver disease. Intake below an Adequate Intake value alone does not diagnose deficiency.","high":"High intakes can cause fishy body odor, excessive sweating or salivation, vomiting, low blood pressure and liver toxicity. The source of choline and individual context matter. An ingredient name or isolated label amount does not establish total exposure, harm or reassurance.","reference":"The US adult upper limit at age 19 and older is 3,500 mg/day choline from all sources, including food and supplements. It is not a personal target or a supplement dose. The 550 mg label Daily Value and sex/life-stage Adequate Intakes have different purposes; no deficiency assessment or personal target is calculated. Children have lower limits.","form":"Choline bitartrate and phosphatidylcholine are distinct named forms. Lecithin is a mixture and cannot be treated as a verified choline amount. Whole-compound mass is not the choline amount, and the reviewed reference does not establish a universal absorption ranking. Alpha-GPC, citicoline, generic lecithin and unreviewed salts are deferred pending form-specific work.","debate":"Choline metabolism can contribute to TMAO production, and some observational studies link TMAO or higher choline intake with adverse outcomes while other studies do not. These associations and mechanisms do not establish that every choline-containing food or supplement causes cardiovascular disease. A biomarker change is not proof of a clinical event.","review":{"date":"2026-10-22","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Choline professional-reference sections.","disclosures":"NIH is the reference publisher, not necessarily the funder of cited studies. Underlying-study funding, author conflicts and sponsor roles were not independently audited; missing disclosures are not a no-conflicts finding.","gaps":"Independent correction/retraction checks and comprehensive current competing-evidence searches remain incomplete. The NIH reference carries a June 2, 2022 update date; alpha-GPC, citicoline, pregnancy-specific treatment and genetic dosing are outside this batch."}}};
function norm(v){return String(v==null?'':v).trim().toLowerCase().replace(/[\u2010-\u2015\u2212]/g,'-').replace(/\s+/g,' ')}
function identify(label){var n=norm(label),hit=null;Object.keys(DATA).some(function(k){return Object.keys(DATA[k].groups).some(function(g){if(DATA[k].groups[g].indexOf(n)>=0){hit={key:k,group:g};return true}return false})});return hit}
function resolveSCC(label,previous){var direct=identify(label);if(direct)return direct.key;var m=/^([^()]+)\s*\(as\s+([^()]+)\)$/.exec(norm(label));if(m){var a=identify(m[1]),b=identify(m[2]);if(a||b)return a&&b&&a.key===b.key&&(a.group==='generic'||a.group===b.group)?a.key:null}return previous(label)}
function install(api){if(!api||!api.entries||!api.sources||!api.reviews||!api.aliases||typeof api.resolve!=='function')throw Error('SCC requires extensible education');if(api.nutrientBatchSCC===VERSION)return api;var keys=Object.keys(DATA),seen=Object.create(null);Object.keys(api.aliases).forEach(function(k){api.aliases[k].forEach(function(n){seen[n]=k})});keys.forEach(function(k){var r=DATA[k];if(api.entries[k]||api.sources[k]||api.aliases[k]||(r.extra&&api.sources[k+'assessment']))throw Error('SCC key collision');Object.keys(r.groups).forEach(function(g){r.groups[g].forEach(function(n){if(seen[n])throw Error('SCC alias collision');seen[n]=k})})});var prior=api.resolve;keys.forEach(function(k){var r=DATA[k],e={};['body','research','high','reference','form'].forEach(function(f){e[f]=[r[f],k]});e.debate=[r.debate,r.extra?k+'assessment':k];api.entries[k]=e;api.sources[k]=[r.title,r.url,'NIH ODS reference; audit partial'];if(r.extra)api.sources[k+'assessment']=r.extra.slice();api.reviews[k]=Object.assign({},r.review);api.aliases[k]=[].concat.apply([],Object.keys(r.groups).map(function(g){return r.groups[g]}))});api.resolve=function(label){return resolveSCC(label,prior)};api.nutrientBatchSCC=VERSION;api.version='0.5.0';return api}
var exported={version:VERSION,records:DATA,identify:identify,resolveSCC:resolveSCC,install:install};if(typeof module==='object'&&module.exports){module.exports=exported;return}if(root.OLNutrientBatchSCC)return;var api=install(root.OLIngredientEducation);root.OLNutrientBatchSCC=exported;if(typeof api.refresh==='function')api.refresh();
})(typeof window==='object'?window:globalThis);
