function install(api){if(!api||!api.entries||!api.sources||!api.reviews||!api.aliases||typeof api.resolve!=='function')throw Error('B batch requires extensible education');if(api.nutrientBatchB===VERSION)return api;var keys=Object.keys(DATA),seen=Object.create(null);Object.keys(api.aliases).forEach(function(k){api.aliases[k].forEach(function(n){seen[n]=k})});keys.forEach(function(k){var r=DATA[k];if(api.entries[k]||api.sources[k]||api.aliases[k]||(r.extra&&api.sources[k+'safety']))throw Error('B batch key collision');Object.keys(r.groups).forEach(function(g){r.groups[g].forEach(function(n){if(seen[n])throw Error('B batch alias collision');seen[n]=k})})});var prior=api.resolve;keys.forEach(function(k){var r=DATA[k],e={};['body','research','high','reference','form'].forEach(function(f){e[f]=[r[f],k]});if(r.debate)e.debate=[r.debate,k+'safety'];api.entries[k]=e;api.sources[k]=[r.title,r.url,'NIH ODS reference; underlying-study audit partial'];if(r.extra)api.sources[k+'safety']=r.extra.slice();api.reviews[k]=Object.assign({},r.review);api.aliases[k]=[].concat.apply([],Object.keys(r.groups).map(function(g){return r.groups[g]}))});api.resolve=function(label){return resolveB(label,prior)};api.nutrientBatchB=VERSION;api.version='0.6.0';return api}
