(function(root){'use strict';
var VERSION='0.1.0',DATA={"manganese":{"title":"Manganese","url":"https://ods.od.nih.gov/factsheets/Manganese-HealthProfessional/","groups":{"generic":["manganese"],"gluconate":["manganese gluconate"],"sulfate":["manganese sulfate","manganese sulphate"],"citrate":["manganese citrate"],"chloride":["manganese chloride"],"picolinate":["manganese picolinate"],"aspartate":["manganese aspartate"],"glycinate":["manganese glycinate","manganese bisglycinate","manganese glycinate chelate","manganese bisglycinate chelate"],"chelate":["manganese amino acid chelate","manganese amino acid chelates"]},"body":"Manganese is a cofactor for enzymes involved in nutrient metabolism, antioxidant processes and bone formation. A normal physiological role does not establish that extra supplementation improves bone health, immunity or glucose control.","research":"The NIH reference describes limited and inconsistent human bone-health associations and mixed manganese-biomarker associations with diabetes. A small calcium/trace-mineral trial cannot isolate manganese’s effect. Animal findings and circulating levels do not establish that a multivitamin prevents osteoporosis or treats diabetes. This is a selected-reference summary, not an exhaustive current trial review.","high":"Excess exposure can cause neurological toxicity, but route matters: inhaled occupational dust findings must not be treated as equivalent to oral intake from food. High-manganese water and impaired bile elimination in chronic liver disease are distinct contexts. Iron deficiency can increase manganese absorption. No exposure history, disease or individual risk is inferred from an ingredient name.","reference":"The US adult upper limit at age 19 and older is 11 mg/day manganese from total intake. Children have lower limits; medically supervised treatment is separate. The 2.3 mg label Daily Value and sex/life-stage Adequate Intakes serve different purposes. Neither is a personal diagnosis or supplement target, and no total intake is calculated.","form":"Named supplement forms include gluconate, sulfate, citrate, chloride, picolinate, aspartate and amino-acid chelates. Supplement Facts declares elemental manganese, not the mass of the whole compound. The cited reference reports no comparative bioavailability data for forms; that does not establish that no newer research exists. No universally superior chelate or manufacturing source is inferred.","debate":"Manganese is not magnesium. Similar spelling is not identity evidence, and a manganese salt must not open magnesium dose education. A neurological toxicity hazard does not mean ordinary manganese-containing food is unsafe; the cited source reports no evidence of toxicity from high dietary intakes in the populations it discusses.","review":{"date":"2026-10-23","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Manganese professional-reference sections. Source page updated March 29, 2021.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of cited studies. Original-study funding, author conflicts, sponsor roles and reference-author relationships were not independently audited; agency publication is not no-conflicts clearance.","gaps":"Independent correction/retraction checks and a comprehensive newer-study search remain incomplete. US reference values are labeled by authority and scope; other jurisdictions’ assessments are not comprehensively reviewed. No personal dose, diagnosis, automatic combination, new color or product safety verdict is added."}},"chromium":{"title":"Chromium","url":"https://ods.od.nih.gov/factsheets/Chromium-HealthProfessional/","groups":{"generic":["chromium"],"picolinate":["chromium picolinate"],"nicotinate":["chromium nicotinate"],"polynicotinate":["chromium polynicotinate"],"chloride":["chromium chloride","chromium(iii) chloride","chromium iii chloride"],"histidinate":["chromium histidinate"],"yeast":["chromium-enriched yeast","chromium enriched yeast"]},"body":"The nutritional reference concerns trivalent chromium (+3), which has been studied for effects on insulin action and metabolism. Its essentiality is disputed: the US reference assessment treated it as essential in 2001, while EFSA concluded in 2014 that convincing evidence of essentiality was lacking. A generic ingredient name does not verify oxidation state or added benefit.","research":"NIH describes inconsistent glycemic-control findings, small or clinically uncertain weight changes and low-quality evidence in some reviews. Statistically significant biomarker changes do not establish meaningful disease prevention or weight-loss benefit. This sheet does not recommend chromium for diabetes, PCOS, obesity or dyslipidemia, and it does not replace treatment.","high":"No established upper limit is not assurance of unlimited safety. The reference notes limited adverse-effect data and isolated case reports involving kidney, liver and other effects; those reports do not establish incidence or prove every product causes harm. Kidney/liver disease and medicines can alter the context. No medication screening or individual suitability assessment is performed.","reference":"The US Food and Nutrition Board has not established a chromium upper intake limit because evidence is insufficient. The 35 mcg label Daily Value and sex/life-stage Adequate Intakes are not upper limits, therapeutic doses or proof that chromium deficiency is present. NIH reports no validated status test or clinically defined deficiency state. No personal target or total intake is calculated.","form":"The reference lists picolinate, nicotinate, polynicotinate, chloride and histidinate supplement forms. Supplement Facts declares elemental chromium, not whole-compound mass. Chromium-enriched yeast is a preparation, not verified pure picolinate. The cited reference concerns nutritional trivalent chromium, not toxic industrial hexavalent chromium; valence, composition and dose are not inferred from generic wording.","debate":"Chromium is included here because it appears in supplement labels and US reference values, not because all authorities agree it is essential. Hexavalent chromium, chromium(VI), chromates and dichromates are excluded from nutrient-dose matching. Qualified or promotional blood-sugar claims are not treated as proven prevention or treatment findings.","review":{"date":"2026-10-23","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Chromium professional-reference sections. Page update date not independently captured in this batch.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of cited studies. Original-study funding, author conflicts, sponsor roles and reference-author relationships were not independently audited; agency publication is not no-conflicts clearance.","gaps":"Independent correction/retraction checks and a comprehensive newer-study search remain incomplete. US reference values are labeled by authority and scope; other jurisdictions’ assessments are not comprehensively reviewed. No personal dose, diagnosis, automatic combination, new color or product safety verdict is added."}},"molybdenum":{"title":"Molybdenum","url":"https://ods.od.nih.gov/factsheets/Molybdenum-HealthProfessional/","groups":{"generic":["molybdenum"],"sodium":["sodium molybdate"],"chloride":["molybdenum chloride"],"glycinate":["molybdenum glycinate"],"chelate":["molybdenum amino acid chelate","molybdenum amino acid chelates"]},"body":"Molybdenum is part of the molybdopterin cofactor needed for enzymes including sulfite oxidase and xanthine oxidase. These normal metabolic roles are not proof that extra supplementation detoxifies the body or treats symptoms.","research":"The NIH reference reports very rare acquired deficiency and does not identify molybdenum as a standard treatment for a disease or disorder. A rare genetic molybdenum-cofactor synthesis disorder is not ordinary dietary deficiency and cannot be assumed to respond to a multivitamin. Enzyme function and an isolated parenteral-nutrition case do not establish benefits from routine extra supplementation.","high":"Human toxicity evidence is limited. A very-high-intake environmental report described gout-like symptoms, but it does not define a precise personal toxicity threshold. The US upper-limit assessment relied on reproductive/developmental effects in rodents because adequate human data were lacking. Occupational exposure, ordinary food intake and supplemental dosing are different contexts.","reference":"The US adult upper limit at age 19 and older is 2,000 mcg/day total molybdenum intake. The 45 mcg adult RDA and label Daily Value are not upper limits or prescribed supplement doses; pregnancy/lactation and younger-age references differ. Keep mcg and mg explicit. No conversion, deficiency diagnosis or total-intake comparison is performed.","form":"The reference lists molybdenum chloride, sodium molybdate, molybdenum glycinate and amino-acid chelates. Its statement that no comparative bioavailability studies were available is not a completed current search or a basis for ranking products. Compound names do not establish elemental amount, absorbed dose or manufacture. Molybdopterin and industrial molybdenum compounds are not exact supplement-dose aliases.","debate":"Sulfite oxidase’s normal function is not evidence that a supplement treats sulfite sensitivity or a generalized detox problem. This app does not diagnose a cofactor disorder, infer genetic suitability or recommend molybdenum treatment. A named sodium molybdate ingredient is not a verified sodium dose.","review":{"date":"2026-10-23","status":"Reference-backed education; partial research audit; not clinically reviewed","read":"Selected NIH ODS Molybdenum professional-reference sections. Source page updated March 30, 2021.","disclosures":"NIH ODS is the reference publisher, not necessarily the funder of cited studies. Original-study funding, author conflicts, sponsor roles and reference-author relationships were not independently audited; agency publication is not no-conflicts clearance.","gaps":"Independent correction/retraction checks and a comprehensive newer-study search remain incomplete. US reference values are labeled by authority and scope; other jurisdictions’ assessments are not comprehensively reviewed. No personal dose, diagnosis, automatic combination, new color or product safety verdict is added."}}};
function norm(v){return String(v==null?'':v).trim().toLowerCase().replace(/[\u2010-\u2015\u2212]/g,'-').replace(/\s+/g,' ')}
function identify(label){var n=norm(label),hit=null;Object.keys(DATA).some(function(k){return Object.keys(DATA[k].groups).some(function(g){if(DATA[k].groups[g].indexOf(n)>=0){hit={key:k,group:g};return true}return false})});return hit}
function resolveTrace(label,previous){var direct=identify(label);if(direct)return direct.key;var m=/^([^()]+)\s*\(as\s+([^()]+)\)$/.exec(norm(label));if(m){var a=identify(m[1]),b=identify(m[2]);if(a||b)return a&&b&&a.key===b.key&&(a.group==='generic'||a.group===b.group)?a.key:null}return previous(label)}
function install(api){if(!api||!api.entries||!api.sources||!api.reviews||!api.aliases||typeof api.resolve!=='function')throw Error('Trace batch requires extensible education');if(api.nutrientBatchTrace===VERSION)return api;var keys=Object.keys(DATA),seen=Object.create(null);Object.keys(api.aliases).forEach(function(k){api.aliases[k].forEach(function(n){seen[n]=k})});keys.forEach(function(k){if(api.entries[k]||api.sources[k]||api.aliases[k])throw Error('Trace key collision');Object.keys(DATA[k].groups).forEach(function(g){DATA[k].groups[g].forEach(function(n){if(seen[n])throw Error('Trace alias collision');seen[n]=k})})});var prior=api.resolve;keys.forEach(function(k){var r=DATA[k],e={};['body','research','high','reference','form','debate'].forEach(function(f){e[f]=[r[f],k]});api.entries[k]=e;api.sources[k]=[r.title,r.url,'NIH ODS reference; original-study audit partial'];api.reviews[k]=Object.assign({},r.review);api.aliases[k]=[].concat.apply([],Object.keys(r.groups).map(function(g){return r.groups[g]}))});api.resolve=function(label){return resolveTrace(label,prior)};api.nutrientBatchTrace=VERSION;api.version='0.7.0';return api}
var exported={version:VERSION,records:DATA,identify:identify,resolveTrace:resolveTrace,install:install};if(typeof module==='object'&&module.exports){module.exports=exported;return}if(root.OLNutrientBatchTrace)return;var api=install(root.OLIngredientEducation);root.OLNutrientBatchTrace=exported;if(typeof api.refresh==='function')api.refresh();
})(typeof window==='object'?window:globalThis);
