/* --- nutrient-batch-electrolytes.js --- */
(function(root){'use strict';
var D={"phosphorus":["Phosphorus","https://ods.od.nih.gov/factsheets/Phosphorus-HealthProfessional/",["dipotassium phosphate","disodium phosphate"],["Phosphorus supports bones, teeth, DNA, cell membranes and ATP-dependent energy processes. A normal nutrient role does not establish benefit from extra supplementation.","NIH describes inconsistent observational associations of phosphate levels or intake with cardiovascular outcomes. Blood levels, dietary intake and treatment effects are different exposures. Kidney-disease evidence does not establish benefit from phosphorus restriction in healthy adults. This is a reference synthesis, not a completed trial audit.","Impaired kidney function can reduce phosphate excretion. Large medicinal phosphate loads can cause serious disturbances; bowel-preparation exposure is not equivalent to an unspecified food additive. An ingredient name does not establish blood phosphate, intake or individual risk.","The US adult RDA is 700 mg/day; the label Daily Value is 1,250 mg. The US total-intake upper limit for healthy nonpregnant adults is 4,000 mg/day at ages 19-70 and 3,000 mg/day at 71 and older. Pregnancy, younger ages and medical treatment differ. These are not supplement targets or kidney-disease prescriptions. No intake comparison is performed.","NIH lists dipotassium phosphate and disodium phosphate as supplement phosphate salts. Phosphorus amount is not whole-compound mass. Food matrix and form affect absorption; phytate-bound plant phosphorus and inorganic phosphate additives are not interchangeable. Phospholipids contain phosphorus but are not automatically matched as verified phosphorus doses.","Phosphate level associations cannot prove that a specific additive causes cardiovascular disease. NIH describes limited clinical-outcome evidence for dietary restriction in kidney disease and tradeoffs with protein intake. No phosphorus-calcium ratio, absorbed dose or product safety verdict is inferred."]],"chloride":["Chloride","https://www.efsa.europa.eu/en/efsajournal/pub/5779",["sodium chloride","potassium chloride","calcium chloride","magnesium chloride"],["Chloride is an electrolyte involved in fluid and acid-base balance. Chloride is not chlorine disinfectant. The name alone does not establish deficiency or a need for extra supplementation.","EFSA reported no appropriate biomarkers, balance studies or adequate chloride-intake/health-outcome evidence for directly setting reference values. It derived chloride values equimolar to sodium reference values, considering their closely linked balances and sodium chloride as the main dietary source.","Sodium chloride contributes both sodium and chloride; evidence about salt cannot automatically isolate an independent chloride effect. Other chloride salts have different accompanying ions and clinical contexts. No kidney function, blood electrolyte status, medication suitability or risk threshold is inferred from the name.","EFSA 2019 considers 3.1 g/day chloride safe and adequate for the general EU adult population, including pregnancy and lactation; younger ages differ. This is not a toxicity upper limit, a US label Daily Value or an individualized prescription. No salt-to-chloride conversion or total-intake comparison is performed.","Explicit chloride (as sodium chloride), chloride (as potassium chloride), chloride (as calcium chloride) and chloride (as magnesium chloride) labels can open chloride context. Bare compound names retain existing resolver behavior rather than being reassigned to chloride. Their names do not establish chloride amount, sodium amount or preparation.","The chloride assessment relies on sodium-linked assumptions, not independent trials proving that additional chloride improves hydration or performance. Salt substitutes and electrolyte blends cannot be assumed suitable for everyone. Reference intake, treatment of an electrolyte disorder and a product claim are different questions."]],"sodium":["Sodium","https://www.nationalacademies.org/read/25353/chapter/2",["sodium chloride","sodium bicarbonate","sodium citrate"],["Sodium is an essential electrolyte involved in fluid balance and nerve and muscle function. Physiological necessity does not imply that extra sodium benefits every user or that a sodium-containing ingredient is automatically unsafe.","The National Academies 2019 assessment found high-strength trial evidence that sodium reduction lowers blood pressure and moderate evidence for some cardiovascular outcomes. Effects vary, including with baseline blood pressure. This is a summary of the assessment, not independent review of every underlying study.","Long-term chronic-disease risk and acute toxicity from extreme concentrated intakes are different concerns. Lack of a defined toxicity upper limit does not mean unlimited intake is safe. These population references do not determine individual sodium needs or medical management.","The 2019 US/Canadian adult Adequate Intake is 1,500 mg/day. For ages 14 and older the Chronic Disease Risk Reduction Intake advises reducing intake if above 2,300 mg/day; younger ages differ. The assessment did not establish a sodium toxicity upper limit. The CDRR is not an exact personal safe/harm boundary, and no total intake or product comparison is calculated.","An explicit sodium (as sodium chloride), sodium (as sodium bicarbonate) or sodium (as sodium citrate) label provides sodium-form context, not a verified amount. Sodium is not the mass of salt or the whole compound. Unqualified compound names retain existing identity routing. No elemental conversion, supplement recommendation or oral-rehydration formula is generated.","The 2019 assessment distinguishes the chronic-disease CDRR from the older sodium upper-limit framework. Observational low-intake findings face measurement and confounding limitations; they do not overturn the trial evidence. No conclusion that less is always better in every clinical or exercise setting is inferred."]]},fields=['body','research','high','reference','form','debate'];
function norm(v){return String(v==null?'':v).trim().toLowerCase().replace(/[\u2010-\u2015\u2212]/g,'-').replace(/\s+/g,' ')}
function install(a){if(!a||!a.entries||!a.sources||!a.reviews||!a.aliases||typeof a.resolve!=='function')throw Error('Electrolyte batch requires education API');if(a.nutrientBatchElectrolytes)return a;Object.keys(D).forEach(function(k){if(a.entries[k]||a.sources[k]||a.aliases[k])throw Error('Electrolyte family collision: '+k);Object.keys(a.aliases).forEach(function(old){if(a.aliases[old].indexOf(k)>=0)throw Error('Electrolyte alias collision: '+k)})});var prior=a.resolve;Object.keys(D).forEach(function(k){var r=D[k],e={};fields.forEach(function(f,i){e[f]=[r[3][i],k]});a.entries[k]=e;a.sources[k]=[r[0],r[1],'Agency assessment; partial research audit'];a.aliases[k]=[k];a.reviews[k]={date:'2026-10-23',status:'Reference-backed education; partial audit; not clinically reviewed',read:k==='phosphorus'?'NIH ODS professional fact sheet, updated May 4, 2023.':k==='chloride'?'EFSA 2019 chloride assessment abstract.':'National Academies 2019 sodium/potassium assessment Summary.',disclosures:'Agency publication is not a no-conflicts clearance. Original-study funding, author conflicts, sponsor roles and individual declarations were not independently audited.',gaps:'Comprehensive newer-study search, independent correction/retraction checks and clinical review remain incomplete. No diagnosis, dose extraction, interaction screening, new color or personalized advice is added.'}});a.resolve=function(label){var n=norm(label);if(Object.prototype.hasOwnProperty.call(D,n))return n;var m=/^([^()]+)\s*\(as\s+([^()]+)\)$/.exec(n);if(m){var k=m[1].trim();if(Object.prototype.hasOwnProperty.call(D,k))return D[k][2].indexOf(m[2].trim())>=0?k:null}return prior(label)};a.version='0.8.0';a.nutrientBatchElectrolytes='0.1.0';return a}
if(typeof module==='object'&&module.exports){module.exports={install:install,records:D};return}if(root.OLNutrientBatchElectrolytes)return;var a=install(root.OLIngredientEducation);root.OLNutrientBatchElectrolytes={install:install,records:D};if(typeof a.refresh==='function')a.refresh();
})(typeof window==='object'?window:globalThis);
